class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Collect all substrings (including empty string) of s
        subs_s = [""]
        n = len(s)
        for i in range(n):
            for j in range(i + 1, n + 1):
                subs_s.append(s[i:j])

        # Collect all substrings (including empty string) of t
        subs_t = [""]
        m = len(t)
        for i in range(m):
            for j in range(i + 1, m + 1):
                subs_t.append(t[i:j])

        max_len = 0
        for a in subs_s:
            la = len(a)
            for b in subs_t:
                total_len = la + len(b)
                if total_len <= max_len:
                    continue
                cand = a + b
                if cand == cand[::-1]:
                    max_len = total_len
        return max_len
