class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        positions = {}
        for i, val in enumerate(nums):
            positions.setdefault(val, []).append(i)

        nearest = [-1] * n

        for indices in positions.values():
            m = len(indices)
            if m == 1:
                continue
            for k, idx in enumerate(indices):
                prev = indices[(k - 1) % m]
                nxt = indices[(k + 1) % m]
                # Circular gaps to the previous and next occurrence
                gap_next = (nxt - idx) % n
                gap_prev = (idx - prev) % n
                nearest[idx] = min(gap_next, gap_prev)

        return [nearest[q] for q in queries]
