from typing import List

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # We can delete any elements, so we can keep exactly one occurrence
        # of each distinct positive value and remove everything else.
        # The kept values form a contiguous subarray with unique elements.
        distinct_positives = {x for x in nums if x > 0}
        if distinct_positives:
            return sum(distinct_positives)
        # No positive values: best choice is a single maximum element.
        return max(nums)
